export function isPort(value) {
  return Number.isInteger(value) && value >= 1 && value <= 65535;
}

export function isIntInRange(value, lo, hi) {
  return Number.isInteger(value) && value >= lo && value <= hi;
}

/** Comment header used by every generated file. */
export function banner(version, title) {
  return '# generated by homepub v' + version + ' - ' + title + '\n' +
    '# Do not edit by hand: change homepub.config.json and run "homepub apply" again.\n';
}

/** Map<string, {content, mode}> -> stable sorted entries (deterministic output/tests). */
export function sortFiles(files) {
  return [...files.entries()].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
}
